/**
 * A simple Java program to add two large numbers represented as strings.
 * This approach simulates manual column addition, handling carries.
 */
public class AddStrings {
    public String addStrings(String num1, String num2) {
        int i = num1.length() - 1; 
        int j = num2.length() - 1; 
        int carry = 0;
        StringBuilder sb = new StringBuilder();

        // Continue as long as there are digits in either number or a carry exists
        while (i >= 0 || j >= 0 || carry > 0) {
            // Get digit from num1, or 0 if num1 is exhausted
            int x = (i >= 0) ? num1.charAt(i) - '0' : 0; 
            // Get digit from num2, or 0 if num2 is exhausted
            int y = (j >= 0) ? num2.charAt(j) - '0' : 0; 

            // Calculate sum for current position
            int sum = x + y + carry;

            // Append the last digit of the sum to the result
            sb.append(sum % 10); 
            // Update carry for the next iteration
            carry = sum / 10;    

            // Move to the next digit (leftwards)
            i--;
            j--;
        }

        // The result was built in reverse, so reverse it back and convert to String
        return sb.reverse().toString();
    }
}

