public class ArrayRotation {
    public static void rotateRight(int[] nums, int k) {
        // Handle edge cases: null array, empty array
        if (nums == null || nums.length == 0) {
            return;
        }

        int n = nums.length;
        // Normalize k: if k is larger than n, or k is negative, it should be within [0, n-1]
        k = k % n;

        // If k is 0 after normalization, no rotation is needed
        if (k == 0) {
            return;
        }

        // The three-reversal algorithm for right rotation:
        // 1. Reverse the entire array
        reverse(nums, 0, n - 1);
        // Example: [1,2,3,4,5], k=2 -> [5,4,3,2,1]

        // 2. Reverse the first k elements
        reverse(nums, 0, k - 1);
        // Example: [5,4,3,2,1] -> [4,5,3,2,1] (for k=2)

        // 3. Reverse the remaining (n-k) elements
        reverse(nums, k, n - 1);
        // Example: [4,5,3,2,1] -> [4,5,1,2,3] (for k=2)
    }

    /**
     * Helper method to reverse a portion of an array.
     * @param nums The array to reverse.
     * @param start The starting index (inclusive).
     * @param end The ending index (inclusive).
     */
    private static void reverse(int[] nums, int start, int end) {
        while (start < end) {
            int temp = nums[start];
            nums[start] = nums[end];
            nums[end] = temp;
            start++;
            end--;
        }
    }
}

